iterations.reply:
The `http-client` capability needed for the enrichment fetch is not in this node's `with` clause, which grants only `inference-llm`. I've left that fetch out, so the output is unchanged by omission. Adding it would also send the raw customer text in a URL to an external host.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{raw-message, customer-query};

    import aap:caps/inference-llm@0.1.0;

    export run: func(message: raw-message) -> customer-query;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm;
use crate::aap::caps::types::Intent;

const MAX_INPUT_CHARS: usize = 4000;
const MAX_QUESTION_CHARS: usize = 512;
const MAX_ENTITIES: usize = 32;
const MAX_ENTITY_CHARS: usize = 128;

const SYSTEM: &str = "You classify one customer message. Reply with exactly three lines and nothing else.\n\
Line 1: one of billing_question, technical_support, account_change, general_inquiry, unknown.\n\
Line 2: the customer's question restated in one sentence.\n\
Line 3: comma-separated account or product names mentioned, or empty.";

struct Node;

/// Keep at most `max` Unicode scalar values (matches Python's `len` on str).
fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

/// Closed intent set: anything not matched exactly is `Unknown`.
fn parse_intent(s: &str) -> Intent {
    match s.trim().to_ascii_lowercase().as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Defensive bound; the node's requires already guarantees this.
        let text = truncate_chars(&message.text, MAX_INPUT_CHARS);

        let reply = inference_llm::infer(SYSTEM, &text, "classify");
        let mut lines = reply.lines();

        let intent = parse_intent(lines.next().unwrap_or(""));

        let question_line = lines.next().unwrap_or("").trim();
        let question_src = if question_line.is_empty() {
            text.trim()
        } else {
            question_line
        };
        let question = truncate_chars(question_src, MAX_QUESTION_CHARS);

        let entities: Vec<String> = lines
            .next()
            .unwrap_or("")
            .split(',')
            .map(str::trim)
            .filter(|e| !e.is_empty())
            .take(MAX_ENTITIES)
            .map(|e| truncate_chars(e, MAX_ENTITY_CHARS))
            .collect();

        CustomerQuery {
            intent,
            entities,
            question,
        }
    }
}

export!(Node);
```

